"""Detect and screen S2 DAS events using stage-conditioned reference domains."""
from __future__ import annotations
import base64
import gzip
import hashlib
import types
import json
import math
import sys
from pathlib import Path
REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
from typing import Callable
import numpy as np
import pandas as pd
WORK_DIR = REPOSITORY_ROOT
S2_INPUT_DIR = REPOSITORY_ROOT / 'data/screening_inputs/S2'
H5_INPUT_DIR = REPOSITORY_ROOT / 'data/raw/S2'
OUTPUT_DIR = REPOSITORY_ROOT / 'outputs/screening/S2'
FIGURE_DIR = REPOSITORY_ROOT / 'outputs/screening/S2/figures'
REVIEW_DIR = REPOSITORY_ROOT / 'outputs/screening/S2/review'
_EMBEDDED_S1_RAW_B64 = ''
_EMBEDDED_REFINER_B64 = ''
LAYOUT_CSV = S2_INPUT_DIR / 'S2_monitoring_channel_layout.csv'
STAGE_CSV = S2_INPUT_DIR / 'S2_hydraulic_stage_blocks.csv'
REFERENCE_WINDOW_CSV = S2_INPUT_DIR / 'S2_background_reference_windows.csv'
NUISANCE_CSV = S2_INPUT_DIR / 'S2_known_nuisance_intervals.csv'
CONFIG_JSON = S2_INPUT_DIR / 'S2_screening_configuration.json'
MACRO_OBSERVATION = pd.Timestamp('2025-07-19 20:37:47')
ANALYSIS_END = pd.Timestamp('2025-07-19 20:40:00')
MAX_SCALE_S = 2.0
REFERENCE_SAFE_END = MACRO_OBSERVATION - pd.Timedelta(seconds=MAX_SCALE_S / 2)
CANDIDATE_FEATURE_SAFE_END = ANALYSIS_END - pd.Timedelta(seconds=MAX_SCALE_S / 2)
REFERENCE_SUBCLASS_COUNTS = {'initial_rain_background': 80, 'early_hydraulic_background': 80, 'stable_hydraulic_background': 80, 'routine_personnel': 60, 'pipe_repair_personnel': 60, 'pipe_burst_flow': 120, 'mixed_personnel_pumping': 60}
REFERENCE_SUBCLASS_TO_PARENT = {'initial_rain_background': 'stable_rain', 'early_hydraulic_background': 'stable_rain', 'stable_hydraulic_background': 'stable_rain', 'routine_personnel': 'personnel', 'pipe_repair_personnel': 'personnel', 'pipe_burst_flow': 'pumping', 'mixed_personnel_pumping': 'pumping'}
REFERENCE_COUNTS = {parent: sum((count for subclass, count in REFERENCE_SUBCLASS_COUNTS.items() if REFERENCE_SUBCLASS_TO_PARENT[subclass] == parent)) for parent in ('stable_rain', 'personnel', 'pumping')}
RAIN_REFERENCE_CLASSES = ('initial_rain_background', 'early_hydraulic_background', 'stable_hydraulic_background')
EARLY_REFERENCE_CLASS = 'early_rain_background'
EARLY_REFERENCE_MAX_EVENTS = 240

def _decode_embedded_source(payload: str, label: str) -> str:
    try:
        return gzip.decompress(base64.b64decode(payload)).decode('utf-8')
    except Exception as exc:
        raise RuntimeError(f'Unable to load embedded {label} source.') from exc

def require_inputs() -> None:
    required = [LAYOUT_CSV, STAGE_CSV, REFERENCE_WINDOW_CSV, NUISANCE_CSV, CONFIG_JSON]
    missing = [str(path) for path in required if not path.exists()]
    if missing:
        raise FileNotFoundError('Missing S2 screening inputs:\n' + '\n'.join(missing))
    if not H5_INPUT_DIR.exists():
        raise FileNotFoundError(f'S2 H5 directory not found: {H5_INPUT_DIR}')

def load_s1_script():
    """Create in-memory S1/refiner modules bundled in this single file."""
    refiner_name = 'screening_features'
    refine = types.ModuleType(refiner_name)
    refine.__file__ = '<embedded S1 multiscale refiner>'
    sys.modules[refiner_name] = refine
    exec(compile(_decode_embedded_source(_EMBEDDED_REFINER_B64, 'S1 refiner'), refine.__file__, 'exec'), refine.__dict__)
    base_name = 's2_embedded_s1_raw_pipeline'
    base = types.ModuleType(base_name)
    base.__file__ = str(Path(__file__).resolve())
    sys.modules[base_name] = base
    exec(compile(_decode_embedded_source(_EMBEDDED_S1_RAW_B64, 'S1 raw-H5 pipeline'), base.__file__, 'exec'), base.__dict__)
    return base

def read_s2_inputs() -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame, dict]:
    metadata = pd.read_csv(LAYOUT_CSV)
    stages = pd.read_csv(STAGE_CSV)
    windows = pd.read_csv(REFERENCE_WINDOW_CSV)
    nuisance = pd.read_csv(NUISANCE_CSV)
    config = json.loads(CONFIG_JSON.read_text(encoding='utf-8'))
    for frame in [stages, windows, nuisance]:
        for name in ['start_time', 'end_time', 'center_time']:
            if name in frame:
                try:
                    frame[name] = pd.to_datetime(frame[name], format='mixed')
                except TypeError:
                    frame[name] = pd.to_datetime(frame[name])
    metadata['data_channel'] = pd.to_numeric(metadata['data_channel'], errors='raise').astype(int)
    metadata['burial_depth_cm'] = pd.to_numeric(metadata['burial_depth_cm'], errors='raise')
    metadata['geometry_type'] = metadata['geometry_type'].astype(str).str.lower()
    return (metadata, stages, windows, nuisance, config)

def canonical_noise_kind(kind: object) -> str:
    """Map S2 nuisance tags to the original S1 hard-exclusion interface."""
    text = str(kind).lower()
    return 'personnel' if text == 'personnel' else 'pumping'
MERGED_EVENT_COLUMNS = ['physical_event_id', 'start_time', 'end_time', 'peak_time', 'representative_data_channel', 'representative_layout_channel', 'representative_sensor_id', 'representative_segment_id', 'geometry_type', 'burial_depth_cm', 'x_cm', 'y_cm', 'stage_id', 'file_name', 'file_index', 'source_data_channels', 'source_min_data_channel', 'source_max_data_channel', 'primitive_count', 'detected_scale_count', 'detected_scales', 'max_detection_score', 'strict_core_1s', 'strict_candidate', 'expanded_candidate', 'local_priority', 'early_caution', 'negative_control_period', 'common_mode_or_leadin', 'instrument_anomaly', 'base_known_human_like', 'exact_operation_overlap', 'exact_operation_kind', 'buffered_operation_overlap', 'buffered_operation_kind', 'seconds_from_macro_observation']
MERGED_MEMBER_COLUMNS = ['physical_event_id', 'primitive_id']

def install_stage4_cache_repair(base) -> None:
    original_merge_primitives: Callable = base.merge_primitives

    def ensure_event_schema(frame: pd.DataFrame) -> pd.DataFrame:
        """Return an event table that always has the complete expected schema."""
        if frame is None:
            return pd.DataFrame(columns=MERGED_EVENT_COLUMNS)
        result = frame.copy()
        for column in MERGED_EVENT_COLUMNS:
            if column not in result.columns:
                result[column] = np.nan
        return result.reindex(columns=MERGED_EVENT_COLUMNS)

    def ensure_member_schema(frame: pd.DataFrame) -> pd.DataFrame:
        """Return a member table that always has the complete expected schema."""
        if frame is None:
            return pd.DataFrame(columns=MERGED_MEMBER_COLUMNS)
        result = frame.copy()
        for column in MERGED_MEMBER_COLUMNS:
            if column not in result.columns:
                result[column] = np.nan
        return result.reindex(columns=MERGED_MEMBER_COLUMNS)

    def merge_primitives_safe(primitives: pd.DataFrame, event_prefix: str='RGM', progress_label: str='merge') -> tuple[pd.DataFrame, pd.DataFrame]:
        """
        Preserve the original merge algorithm.

        The only change is that a zero-event result still carries valid CSV
        headers, preventing EmptyDataError on later reuse.
        """
        if primitives is None or primitives.empty:
            return (pd.DataFrame(columns=MERGED_EVENT_COLUMNS), pd.DataFrame(columns=MERGED_MEMBER_COLUMNS))
        events, members = original_merge_primitives(primitives, event_prefix=event_prefix, progress_label=progress_label)
        return (ensure_event_schema(events), ensure_member_schema(members))

    def validate_csv_structure(path: Path, required_columns: set[str], parse_dates: tuple[str, ...]=()) -> tuple[bool, str]:
        """
        Validate a Stage-4 CSV/CSV.GZ cache without loading the whole file.

        A header-only zero-row CSV is valid.
        A zero-byte file or a gzip CSV with no header is invalid.
        """
        path = Path(path)
        if not path.exists():
            return (False, '文件不存在')
        try:
            size = path.stat().st_size
        except OSError as exc:
            return (False, f'无法读取文件状态：{type(exc).__name__}: {exc}')
        if size <= 0:
            return (False, '文件大小为0字节')
        try:
            header = pd.read_csv(path, nrows=0)
        except pd.errors.EmptyDataError:
            return (False, 'CSV为空，没有任何列/表头')
        except Exception as exc:
            return (False, f'CSV表头无法读取：{type(exc).__name__}: {exc}')
        missing = sorted(required_columns.difference(header.columns))
        if missing:
            return (False, f'缺少必要字段：{missing}')
        try:
            check = pd.read_csv(path, nrows=5)
            for column in parse_dates:
                if column in check.columns and (not check.empty):
                    parsed = pd.to_datetime(check[column], errors='coerce')
                    if parsed.isna().any():
                        return (False, f'日期字段{column}存在无法解析的值')
        except pd.errors.EmptyDataError:
            return (False, 'CSV无可解析列')
        except Exception as exc:
            return (False, f'CSV内容无法读取：{type(exc).__name__}: {exc}')
        return (True, 'OK')

    def validate_batch_cache(event_path: Path, member_path: Path, meta_path: Path, expected_meta: dict) -> tuple[bool, str]:
        """Validate meta + event CSV + member CSV for one Stage-4 batch."""
        if not meta_path.exists():
            return (False, 'batch JSON不存在')
        try:
            saved_meta = json.loads(meta_path.read_text(encoding='utf-8'))
        except Exception as exc:
            return (False, f'batch JSON损坏：{type(exc).__name__}: {exc}')
        if saved_meta != expected_meta:
            return (False, 'batch JSON与当前配置/源文件不一致')
        event_ok, event_reason = validate_csv_structure(event_path, {'physical_event_id', 'start_time', 'end_time', 'peak_time'}, parse_dates=('start_time', 'end_time', 'peak_time'))
        if not event_ok:
            return (False, f'event缓存异常：{event_reason}')
        member_ok, member_reason = validate_csv_structure(member_path, {'physical_event_id', 'primitive_id'})
        if not member_ok:
            return (False, f'member缓存异常：{member_reason}')
        return (True, 'OK')

    def remove_stale_temp(path: Path) -> None:
        try:
            if path.exists():
                path.unlink()
        except Exception as exc:
            base.log(f'[merge/cache] 警告：无法删除旧临时文件 {path.name}：{exc}')

    def merge_primitives_in_batches_safe(cache_paths: list[Path], records: list, digest: str) -> tuple[pd.DataFrame, pd.DataFrame]:
        """
        Stage-4 safe batch merge.

        Valid batches are reused.
        Only an invalid batch is reconstructed from its already-existing
        per-H5 primitive caches.
        """
        batch_dir = base.OUTPUT_DIR / 'merge_batch_cache' / digest
        batch_dir.mkdir(parents=True, exist_ok=True)
        overlap_s = 2.0 * base.MERGE_MAX_EVENT_SPAN_S + base.MERGE_MAX_PEAK_GAP_S
        batch_event_paths: list[Path] = []
        batch_member_paths: list[Path] = []
        total_batches = int(math.ceil(len(cache_paths) / base.MERGE_BATCH_FILES))
        reused_batches: list[int] = []
        rebuilt_batches: list[int] = []
        for batch_number, first in enumerate(range(0, len(cache_paths), base.MERGE_BATCH_FILES), start=1):
            stop = min(len(cache_paths), first + base.MERGE_BATCH_FILES)
            event_path = batch_dir / f'events_{batch_number:03d}.csv.gz'
            member_path = batch_dir / f'members_{batch_number:03d}.csv.gz'
            meta_path = batch_dir / f'batch_{batch_number:03d}.json'
            relevant_start = max(0, first - 1)
            relevant_stop = min(len(cache_paths), stop + 1)
            meta = {'merge_algorithm_version': 2, 'signature_digest': digest, 'first_file': first, 'stop_file': stop, 'overlap_s': overlap_s, 'merge_parameters': {'peak_gap_s': base.MERGE_MAX_PEAK_GAP_S, 'event_span_s': base.MERGE_MAX_EVENT_SPAN_S, 'envelope_correlation_min': base.ENVELOPE_CORRELATION_MIN, 'spectral_js_max': base.SPECTRAL_JS_MAX, 'adjacent_distance_cm': base.ADJACENT_DISTANCE_CM, 'gauge_intervals': base.GAUGE_INTERVALS}, 'source_files': [base.cache_fingerprint(path) for path in cache_paths[relevant_start:relevant_stop]]}
            reusable, reason = validate_batch_cache(event_path, member_path, meta_path, meta)
            if reusable:
                base.log(f'[merge/batch] {batch_number}/{total_batches} 缓存校验通过，复用批次归并缓存')
                reused_batches.append(batch_number)
                batch_event_paths.append(event_path)
                batch_member_paths.append(member_path)
                continue
            existed_before = event_path.exists() or member_path.exists() or meta_path.exists()
            if existed_before:
                base.log(f'[merge/batch] {batch_number}/{total_batches} 发现异常缓存，仅重新计算该批次；原因={reason}')
            else:
                base.log(f'[merge/batch] {batch_number}/{total_batches} 无可复用批次缓存，开始计算')
            rebuilt_batches.append(batch_number)
            core_start = records[first].start
            if stop < len(records):
                core_end = records[stop].start
            else:
                last_record = records[stop - 1]
                core_end = last_record.start + pd.Timedelta(seconds=last_record.samples / base.SAMPLE_RATE_HZ)
            frames: list[pd.DataFrame] = []
            if first > 0:
                previous = base._read_primitive_cache(cache_paths[first - 1])
                frames.append(previous[previous.peak_time >= core_start - pd.Timedelta(seconds=overlap_s)])
            for path in cache_paths[first:stop]:
                frames.append(base._read_primitive_cache(path))
            if stop < len(cache_paths):
                following = base._read_primitive_cache(cache_paths[stop])
                frames.append(following[following.peak_time < core_end + pd.Timedelta(seconds=overlap_s)])
            working = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()
            base.log(f'[merge/batch] {batch_number}/{total_batches}；核心文件={first + 1}-{stop}；含边界候选={len(working):,}')
            local_events, local_members = merge_primitives_safe(working, event_prefix=f'B{batch_number:03d}', progress_label=f'merge {batch_number}/{total_batches}')
            if not local_events.empty:
                keep = local_events['peak_time'].ge(core_start) & local_events['peak_time'].lt(core_end)
                local_events = local_events.loc[keep].copy()
                keep_ids = set(local_events['physical_event_id'].astype(str))
                local_members = local_members[local_members['physical_event_id'].astype(str).isin(keep_ids)].copy()
            local_events = ensure_event_schema(local_events)
            local_members = ensure_member_schema(local_members)
            event_tmp = event_path.with_name(event_path.name + '.tmp.gz')
            member_tmp = member_path.with_name(member_path.name + '.tmp.gz')
            remove_stale_temp(event_tmp)
            remove_stale_temp(member_tmp)
            local_events.to_csv(event_tmp, index=False, compression='gzip')
            local_members.to_csv(member_tmp, index=False, compression='gzip')
            event_tmp_ok, event_tmp_reason = validate_csv_structure(event_tmp, {'physical_event_id', 'start_time', 'end_time', 'peak_time'}, parse_dates=('start_time', 'end_time', 'peak_time'))
            if not event_tmp_ok:
                raise RuntimeError(f'批次{batch_number:03d}重新生成的event临时缓存仍异常：{event_tmp_reason}')
            member_tmp_ok, member_tmp_reason = validate_csv_structure(member_tmp, {'physical_event_id', 'primitive_id'})
            if not member_tmp_ok:
                raise RuntimeError(f'批次{batch_number:03d}重新生成的member临时缓存仍异常：{member_tmp_reason}')
            event_tmp.replace(event_path)
            member_tmp.replace(member_path)
            base.atomic_write_json(meta_path, meta)
            final_ok, final_reason = validate_batch_cache(event_path, member_path, meta_path, meta)
            if not final_ok:
                raise RuntimeError(f'批次{batch_number:03d}重新计算后缓存验证仍失败：{final_reason}')
            batch_event_paths.append(event_path)
            batch_member_paths.append(member_path)
            base.log(f'[merge/batch] {batch_number}/{total_batches} 重新计算完成并通过校验；事件={len(local_events):,}；成员={len(local_members):,}')
            del working, frames, local_events, local_members
        base.log(f'[merge/check] 批次检查完成；总批次={total_batches}；正常复用={len(reused_batches)}；重新计算={len(rebuilt_batches)}')
        if rebuilt_batches:
            base.log('[merge/check] 本次重新计算批次：' + ','.join((f'{number:03d}' for number in rebuilt_batches)))
        else:
            base.log('[merge/check] 所有批次缓存均完整，无需重新计算')
        base.log('[merge/consolidate] 正在汇总批次事件并统一编号')
        event_frames: list[pd.DataFrame] = []
        member_frames: list[pd.DataFrame] = []
        for batch_number, path in enumerate(batch_event_paths, start=1):
            try:
                frame = pd.read_csv(path, parse_dates=['start_time', 'end_time', 'peak_time'], low_memory=False)
            except Exception as exc:
                raise RuntimeError(f'最终汇总时无法读取event批次{batch_number:03d}：{path}\n{type(exc).__name__}: {exc}') from exc
            event_frames.append(frame)
        for batch_number, path in enumerate(batch_member_paths, start=1):
            try:
                frame = pd.read_csv(path, low_memory=False)
            except Exception as exc:
                raise RuntimeError(f'最终汇总时无法读取member批次{batch_number:03d}：{path}\n{type(exc).__name__}: {exc}') from exc
            member_frames.append(frame)
        nonempty_event_frames = [frame for frame in event_frames if not frame.empty]
        nonempty_member_frames = [frame for frame in member_frames if not frame.empty]
        events = pd.concat(nonempty_event_frames, ignore_index=True) if nonempty_event_frames else pd.DataFrame(columns=MERGED_EVENT_COLUMNS)
        members = pd.concat(nonempty_member_frames, ignore_index=True) if nonempty_member_frames else pd.DataFrame(columns=MERGED_MEMBER_COLUMNS)
        if events.empty:
            base.log('[merge/consolidate] 所有批次均无事件')
            return (events, members)
        events = events.sort_values('peak_time').reset_index(drop=True)
        old_ids = events['physical_event_id'].astype(str).tolist()
        new_ids = [f'RGM_{i + 1:07d}' for i in range(len(events))]
        id_mapping = dict(zip(old_ids, new_ids))
        events['physical_event_id'] = new_ids
        members['physical_event_id'] = members['physical_event_id'].astype(str).map(id_mapping)
        if members['physical_event_id'].isna().any():
            bad_members = int(members['physical_event_id'].isna().sum())
            raise RuntimeError(f'批次成员关系中存在{bad_members}条无法映射的事件编号。')
        base.log(f'[merge/consolidate] 完成：事件={len(events):,}；成员关系={len(members):,}')
        return (events, members)
    base.merge_primitives = merge_primitives_safe
    base.merge_primitives_in_batches = merge_primitives_in_batches_safe
    base.log('[patch] 已启用阶段4批次缓存完整性检查：正常批次复用，异常批次单独重算')

def install_s2_adapter(base) -> None:
    metadata, stages, windows, nuisance, config = read_s2_inputs()
    if not windows['eligible_for_calibration'].fillna(False).astype(bool).any():
        raise ValueError('No S2 background reference window is marked eligible_for_calibration.')
    base.H5_INPUT_DIR = H5_INPUT_DIR
    base.BASE_RESULT_DIR = S2_INPUT_DIR
    base.OUTPUT_DIR = OUTPUT_DIR
    base.FIGURE_DIR = FIGURE_DIR
    base.REVIEW_DIR = REVIEW_DIR
    base.H5_DATASET = str(config['h5_dataset'])
    h5 = config['h5_summary']
    base.SAMPLE_RATE_HZ = float(h5['sampling_rate_hz'])
    base.FILE_DURATION_S = float(h5['samples_per_file']) / float(h5['sampling_rate_hz'])
    base.DATA_CHANNEL_COUNT = int(h5['channel_count'] - 1)
    base.GAUGE_LENGTH_M = float(h5['gauge_length_m'])
    base.CHANNEL_SPACING_M = float(h5['channel_spacing_m'])
    base.GAUGE_INTERVALS = int(round(base.GAUGE_LENGTH_M / base.CHANNEL_SPACING_M))
    base.GAUGE_HALF_CHANNELS = int(np.ceil(base.GAUGE_INTERVALS / 2))
    initial_rain = windows.loc[windows['reference_class'].eq('initial_rain_background')].copy()
    if len(initial_rain) != 1:
        raise ValueError('S2_background_reference_windows.csv must contain exactly one initial_rain_background row (09:00--09:30).')
    base.EXPERIMENT_START = pd.Timestamp(initial_rain['start_time'].iloc[0])
    base.EARLY30_END = pd.Timestamp(initial_rain['end_time'].iloc[0])
    base.MACRO_OBSERVATION = MACRO_OBSERVATION
    base.ANALYSIS_END = ANALYSIS_END
    base.FEATURE_SAFE_END = CANDIDATE_FEATURE_SAFE_END
    base.EARLY30_REFERENCE_CLASS = EARLY_REFERENCE_CLASS
    base.EARLY30_REFERENCE_MAX_EVENTS = EARLY_REFERENCE_MAX_EVENTS
    base.BASELINE_REFERENCE_CLASSES = ('stable_rain', 'personnel', 'pumping')
    base.FOUR_REFERENCE_CLASSES = ('stable_rain', 'personnel', 'pumping', EARLY_REFERENCE_CLASS)
    base.KNOWN_NOISE_INTERVALS = [(str(row.start_time), str(row.end_time), canonical_noise_kind(row.kind)) for row in nuisance.itertuples(index=False)]
    base.PERSONNEL_BUFFER_S = 15.0
    base.PUMPING_BUFFER_S = 30.0
    base.refine.KNOWN_NOISE_INTERVALS = list(base.KNOWN_NOISE_INTERVALS)
    base.refine.PERSONNEL_BUFFER_S = base.PERSONNEL_BUFFER_S
    base.refine.PUMPING_BUFFER_S = base.PUMPING_BUFFER_S
    base.refine.REFERENCE_COUNTS = dict(REFERENCE_COUNTS)
    base.log('[S2/reference-policy] 保持S1统一KNN核心：每尺度合并全部参考、统一LOO阈值；S2按七个实际子类均衡抽样。')

    def load_network_and_stages() -> tuple[pd.DataFrame, pd.DataFrame]:
        return (metadata.copy(), stages.copy())

    def operation_status(time: pd.Timestamp, buffered: bool=True) -> tuple[bool, str]:
        time = pd.Timestamp(time)
        for row in nuisance.itertuples(index=False):
            pad = float(row.buffer_s) if buffered else 0.0
            left = pd.Timestamp(row.start_time) - pd.Timedelta(seconds=pad)
            right = pd.Timestamp(row.end_time) + pd.Timedelta(seconds=pad)
            if left <= time <= right:
                return (True, canonical_noise_kind(row.kind))
        return (False, '')

    def calibration_times(records, blocks: pd.DataFrame) -> pd.DatetimeIndex:
        """S1-equivalent, stage-conditioned S2 background sampling.

        All pre-macro H5 records are sampled every 10 s, documented operation
        intervals (including their buffers) are excluded, and then at most 48
        clean samples are drawn per physical stage.  Thus every analysable S2
        stage receives its own background model without using post-macro data.
        """
        candidates: list[pd.Timestamp] = []
        edge = pd.Timedelta(seconds=5)
        for record in records:
            start = pd.Timestamp(record.start)
            samples = int(getattr(record, 'samples', round(base.FILE_DURATION_S * base.SAMPLE_RATE_HZ)))
            end = start + pd.Timedelta(seconds=samples / base.SAMPLE_RATE_HZ)
            left = start + edge
            right = min(end - edge, REFERENCE_SAFE_END)
            if right <= left:
                continue
            candidates.extend(pd.date_range(left, right, freq='10s', inclusive='left').to_list())
        if not candidates:
            raise RuntimeError('No S2 pre-macro calibration time is covered by the H5 files.')
        times = pd.DatetimeIndex(sorted(set(candidates)))
        clean = np.asarray([not operation_status(time, buffered=True)[0] for time in times], dtype=bool)
        times = times[clean]
        stage_vector = base.stage_ids(times, blocks)
        valid_stage = stage_vector >= 0
        times = times[valid_stage]
        stage_vector = stage_vector[valid_stage]
        if len(times) == 0:
            raise RuntimeError('No non-operation S2 calibration time remains before the macro failure.')
        per_stage = int(getattr(base, 'CALIBRATION_TIMES_PER_STAGE', 48))
        rng = np.random.default_rng(base.RANDOM_SEED)
        selected: list[int] = []
        summary: list[str] = []
        for stage_id in sorted(np.unique(stage_vector)):
            local = np.flatnonzero(stage_vector == stage_id)
            number = min(per_stage, len(local))
            if number:
                selected.extend(rng.choice(local, size=number, replace=False).tolist())
                summary.append(f'{int(stage_id)}:{number}')
        result = times[np.asarray(sorted(selected), dtype=int)]
        if len(result) == 0:
            raise RuntimeError('S2 has no valid stage-conditioned calibration samples.')
        base.log(f'[S2/calibration] 阶段条件背景样本={len(result)}；各阶段(阶段:样本数)=' + ', '.join(summary))
        return result
    stage_table = stages.copy()
    stage_table['start_time'] = pd.to_datetime(stage_table['start_time'])
    stage_table['end_time'] = pd.to_datetime(stage_table['end_time'])
    post_macro_stage_ids = stage_table.loc[stage_table['start_time'].ge(MACRO_OBSERVATION), 'stage_id'].astype(int).tolist()
    pre_macro_stage_ids = stage_table.loc[stage_table['end_time'].le(MACRO_OBSERVATION), 'stage_id'].astype(int).tolist()
    if not post_macro_stage_ids or not pre_macro_stage_ids:
        raise RuntimeError('S2 stage table must contain both pre- and post-macro stages.')
    POST_MACRO_STAGE_IDS = sorted(post_macro_stage_ids)
    POST_MACRO_ANCHOR_STAGE_ID = max(pre_macro_stage_ids)
    original_build_calibration: Callable = base.build_calibration

    def build_calibration_with_post_macro_holdout(*args, **kwargs):
        """Keep Stage 7 out of calibration but supply it a frozen stage-6 model."""
        samples, models = original_build_calibration(*args, **kwargs)
        if models is None or models.empty or 'stage_id' not in models:
            raise RuntimeError('S2 calibration produced no stage-specific background models.')
        model_stage = pd.to_numeric(models['stage_id'], errors='coerce')
        anchor = models.loc[model_stage.eq(POST_MACRO_ANCHOR_STAGE_ID)].copy()
        if anchor.empty:
            if args and len(args[0]) == 1:
                base.log('[S2/post-macro] smoke模式：未覆盖阶段6，跳过阶段7冻结模型。')
                return (samples, models)
            available = sorted(model_stage.dropna().astype(int).unique().tolist())
            raise RuntimeError(f'Missing the final pre-macro S2 calibration model for stage {POST_MACRO_ANCHOR_STAGE_ID}; available stages={available}.')
        copies = [models]
        for stage_id in POST_MACRO_STAGE_IDS:
            copy = anchor.copy()
            copy['stage_id'] = int(stage_id)
            copies.append(copy)
        scan_models = pd.concat(copies, ignore_index=True)
        base.log(f'[S2/post-macro] 阶段 {POST_MACRO_STAGE_IDS} 不参与背景校准；扫描暂用阶段 {POST_MACRO_ANCHOR_STAGE_ID} 的冻结模型。')
        return (samples, scan_models)
    feature_h5_coverage_cache: list[tuple[pd.Timestamp, pd.Timestamp]] | None = None

    def get_feature_h5_coverage() -> list[tuple[pd.Timestamp, pd.Timestamp]]:
        """
        Return the actual H5 time intervals available to the old multiscale
        feature extractor.

        This is evaluated lazily in Stage 5, after configure_refiner() has
        installed the S2 H5 directory in the shared refiner.
        """
        nonlocal feature_h5_coverage_cache
        if feature_h5_coverage_cache is not None:
            return feature_h5_coverage_cache
        records_local = base.refine.list_h5_records()
        records_local = [record for record in records_local if pd.Timestamp(record.start) < ANALYSIS_END]
        if not records_local:
            raise RuntimeError('Stage 5 cannot find any S2 H5 record before ANALYSIS_END.')
        coverage: list[tuple[pd.Timestamp, pd.Timestamp]] = []
        for record in records_local:
            start = pd.Timestamp(record.start)
            samples = int(getattr(record, 'samples', round(base.FILE_DURATION_S * base.SAMPLE_RATE_HZ)))
            end = start + pd.Timedelta(seconds=samples / base.SAMPLE_RATE_HZ)
            coverage.append((start, end))
        coverage.sort(key=lambda pair: pair[0])
        feature_h5_coverage_cache = coverage
        base.log(f'[feature/H5] 实际H5覆盖：首文件={coverage[0][0]}；末文件结束≈{coverage[-1][1]}；文件数={len(coverage)}')
        return feature_h5_coverage_cache

    def time_is_inside_h5(time: pd.Timestamp, coverage: list[tuple[pd.Timestamp, pd.Timestamp]], margin_s: float=0.0) -> bool:
        t = pd.Timestamp(time)
        margin = pd.Timedelta(seconds=float(margin_s))
        return any((start + margin <= t < end - margin for start, end in coverage if (end - start).total_seconds() > 2.0 * margin_s))

    def sample_times(intervals: pd.DataFrame, count: int, rng: np.random.Generator, label: str, balance_by_interval: bool=False) -> pd.DatetimeIndex:
        """
        Sample S2 reference times with the same H5-interior rule as S1.

        S1 creates calibration times at a 10-s interval, beginning 5 s after
        every H5 start and stopping 5 s before its end.  S2 retains exactly
        that conservative H5 geometry, then intersects it with the documented
        stable-hydraulic/personnel/pumping intervals and the pre-macro limit.
        """
        coverage = get_feature_h5_coverage()
        raw_context_s = float(getattr(base.refine, 'RAW_CONTEXT_S', 4.0))
        feature_margin_s = max(2.0, raw_context_s / 2.0 + 0.1)
        h5_edge = pd.Timedelta(seconds=5)
        interval_values: list[tuple[str, list[pd.Timestamp]]] = []
        for row in intervals.itertuples(index=False):
            interval_start = pd.Timestamp(row.start_time) + pd.Timedelta(seconds=2)
            interval_end = min(pd.Timestamp(row.end_time) - pd.Timedelta(seconds=2), REFERENCE_SAFE_END)
            if interval_end <= interval_start:
                continue
            values: list[pd.Timestamp] = []
            for h5_start, h5_end in coverage:
                grid = pd.date_range(h5_start + h5_edge, h5_end - h5_edge, freq='10s', inclusive='left')
                values.extend((pd.Timestamp(value) for value in grid if interval_start <= pd.Timestamp(value) <= interval_end))
            values = sorted(set((pd.Timestamp(value) for value in values)))
            values = [value for value in values if time_is_inside_h5(value, coverage, margin_s=feature_margin_s)]
            if values:
                interval_name = str(getattr(row, 'reference_class', getattr(row, 'kind', label)))
                interval_values.append((interval_name, values))
        values = sorted({value for _, local in interval_values for value in local})
        if not values:
            first_h5 = coverage[0][0]
            last_h5 = coverage[-1][1]
            raise RuntimeError(f'No valid H5-covered feature times for S2 reference class {label!r}. H5 coverage is {first_h5} -- {last_h5}; check the corresponding S2 reference/nuisance log.')
        allocation_summary: list[str] = []
        if balance_by_interval:
            number_of_intervals = len(interval_values)
            base_count, remainder = divmod(int(count), number_of_intervals)
            chosen_parts: list[np.ndarray] = []
            replacement_used = False
            for index, (interval_name, local_values) in enumerate(interval_values):
                local_count = base_count + (1 if index < remainder else 0)
                local_array = np.asarray(local_values, dtype='datetime64[ns]')
                local_replace = len(local_array) < local_count
                replacement_used |= local_replace
                chosen_parts.append(rng.choice(local_array, size=local_count, replace=local_replace))
                allocation_summary.append(f'{interval_name}:{local_count}/{len(local_array)}')
            chosen = np.concatenate(chosen_parts)
            chosen = chosen[rng.permutation(len(chosen))]
            replace = replacement_used
        else:
            array = np.asarray(values, dtype='datetime64[ns]')
            replace = len(array) < count
            chosen = rng.choice(array, size=count, replace=replace)
        result = pd.DatetimeIndex(chosen)
        bad = [pd.Timestamp(time) for time in result if not time_is_inside_h5(pd.Timestamp(time), coverage, margin_s=feature_margin_s)]
        if bad:
            raise RuntimeError(f'Internal error: {label} sampled {len(bad)} reference times outside H5 coverage; first bad time={bad[0]}')
        base.log(f'[feature/reference] {label}：有效可采样时刻={len(values):,}；抽取={count}；有放回={replace}；H5边缘保护=5s（S1同规则）；范围={result.min()} -- {result.max()}')
        if allocation_summary:
            base.log('[feature/reference-balance] ' + label + ' 各降雨阶段(抽取/可用)=' + ', '.join(allocation_summary))
        return result

    def sample_sensors(count: int, rng: np.random.Generator) -> pd.DataFrame:
        targets = metadata[metadata['analysis_role'].eq('target')].copy()
        targets['stratum'] = targets['burial_depth_cm'].round(3).astype(str) + '|' + targets['geometry_type']
        groups = [group.reset_index(drop=True) for _, group in targets.groupby('stratum', sort=True)]
        if not groups:
            raise RuntimeError('S2 monitoring table has no target sensors.')
        return pd.DataFrame([groups[i % len(groups)].iloc[int(rng.integers(0, len(groups[i % len(groups)])))] for i in range(count)]).reset_index(drop=True)

    def build_feature_tasks(events: pd.DataFrame, table: pd.DataFrame, blocks: pd.DataFrame, max_events=None) -> pd.DataFrame:
        candidate = events.copy()
        if max_events is not None and len(candidate) > max_events:
            candidate = candidate.sort_values('peak_time').head(int(max_events)).copy()
        event_tasks = pd.DataFrame({'task_id': 'candidate:' + candidate['physical_event_id'].astype(str), 'task_class': 'candidate', 'physical_event_id': candidate['physical_event_id'].astype(str), 'time': pd.to_datetime(candidate['peak_time']), 'data_channel': candidate['representative_data_channel'].astype(int), 'geometry_type': candidate['geometry_type'].astype(str).str.lower(), 'burial_depth_cm': candidate['burial_depth_cm'].astype(float), 'segment_id': candidate['representative_segment_id'].astype(str), 'stage_id': candidate['stage_id'].astype(int)})
        eligible = windows['eligible_for_calibration'].fillna(False).astype(bool)
        nuisance_kind = nuisance['kind'].astype(str).str.lower()
        nuisance_note = nuisance.get('note', pd.Series('', index=nuisance.index, dtype=object)).astype(str).str.lower()
        repair_personnel = nuisance_kind.eq('personnel') & nuisance_note.str.contains('repair', regex=False)
        reference_intervals = {'initial_rain_background': windows[eligible & windows['reference_class'].eq('initial_rain_background')], 'early_hydraulic_background': windows[eligible & windows['reference_class'].eq('early_hydraulic_background')], 'stable_hydraulic_background': windows[eligible & windows['reference_class'].eq('stable_hydraulic_background')], 'routine_personnel': nuisance[nuisance_kind.eq('personnel') & ~repair_personnel], 'pipe_repair_personnel': nuisance[repair_personnel], 'pipe_burst_flow': nuisance[nuisance_kind.eq('pipe_burst_flow')], 'mixed_personnel_pumping': nuisance[nuisance_kind.eq('mixed_personnel_pumping')]}
        missing_reference = [label for label, frame in reference_intervals.items() if frame.empty]
        if missing_reference:
            raise RuntimeError('S2 reference configuration has no intervals for: ' + ', '.join(missing_reference))
        rng = np.random.default_rng(base.RANDOM_SEED)
        rows = []
        balance_subclasses = {'mixed_personnel_pumping'}
        for subclass, count in REFERENCE_SUBCLASS_COUNTS.items():
            times = sample_times(reference_intervals[subclass], count, rng, label=subclass, balance_by_interval=subclass in balance_subclasses)
            sensors = sample_sensors(count, rng)
            stage_ids = base.stage_ids(times, blocks)
            for number, (time, sensor) in enumerate(zip(times, sensors.itertuples(index=False))):
                rows.append({'task_id': f'{subclass}:{number:05d}', 'task_class': REFERENCE_SUBCLASS_TO_PARENT[subclass], 'physical_event_id': '', 'time': pd.Timestamp(time), 'data_channel': int(sensor.data_channel), 'geometry_type': str(sensor.geometry_type).lower(), 'burial_depth_cm': float(sensor.burial_depth_cm), 'segment_id': str(sensor.segment_id), 'stage_id': int(stage_ids[number])})
        tasks = pd.concat([event_tasks, pd.DataFrame(rows)], ignore_index=True)
        tasks['time'] = pd.to_datetime(tasks['time'], errors='coerce')
        coverage = get_feature_h5_coverage()
        covered = tasks['time'].map(lambda value: False if pd.isna(value) else time_is_inside_h5(pd.Timestamp(value), coverage, margin_s=0.0)).astype(bool)
        if not covered.all():
            bad = tasks.loc[~covered, ['task_id', 'task_class', 'time']].copy()
            preview = bad.head(10).to_dict('records')
            raise RuntimeError(f'Stage 5 task validation failed: {len(bad)} tasks are outside actual H5 coverage. Examples={preview}')
        base.log(f'[feature/task-check] H5时间覆盖校验通过：{len(tasks):,}/{len(tasks):,} 个任务')
        return tasks

    def s2_task_cache_signature(tasks: pd.DataFrame) -> str:
        """Hash the actual S2 task identity, not only its row count/range.

        The embedded S1 cache signature does not include sampled reference
        times or classes.  Two different S2 noise configurations can therefore
        have the same old signature when their total task count is unchanged.
        """
        columns = ['task_id', 'task_class', 'physical_event_id', 'time', 'data_channel', 'geometry_type', 'burial_depth_cm', 'stage_id']
        work = tasks[columns].copy()
        work['time'] = pd.to_datetime(work['time'], errors='coerce').astype('int64')
        for column in ['task_id', 'task_class', 'physical_event_id', 'geometry_type']:
            work[column] = work[column].astype(str)
        row_hash = pd.util.hash_pandas_object(work, index=False).to_numpy(np.uint64)
        digest = hashlib.sha256(row_hash.tobytes())
        digest.update(repr((tuple(getattr(base.refine, 'ANALYSIS_SCALES_S', ())), float(getattr(base.refine, 'RAW_CONTEXT_S', 0.0)), tuple(REFERENCE_SUBCLASS_COUNTS.items()), tuple(REFERENCE_SUBCLASS_TO_PARENT.items()))).encode('utf-8'))
        return digest.hexdigest()

    def attach_reference_subclass(features: pd.DataFrame) -> pd.DataFrame:
        result = features.copy()
        prefix = result['task_id'].astype(str).str.split(':', n=1).str[0]
        is_candidate = result['task_class'].astype(str).eq('candidate')
        result['reference_subclass'] = np.where(is_candidate, 'candidate', prefix)
        return result

    def add_subclass_diagnostics(scored: pd.DataFrame, z_all: np.ndarray, subclasses: tuple[str, ...]) -> pd.DataFrame:
        """Add nearest S2 subclass diagnostics without changing pooled KNN."""
        result = scored.copy()
        if 'reference_subclass' not in result:
            result = attach_reference_subclass(result)
        z = np.asarray(z_all, dtype=float)
        if z.ndim != 2 or len(z) != len(result):
            raise RuntimeError('S2 subclass diagnostics: z matrix does not match rows.')
        result['nearest_noise_subclass'] = ''
        result['nearest_noise_subclass_distance'] = np.nan
        scale_values = pd.to_numeric(result['scale_s'], errors='coerce').to_numpy(float)
        subclass_values = result['reference_subclass'].astype(str)
        k_neighbors = int(getattr(base.refine, 'K_NEIGHBORS', 10))
        for scale in base.refine.ANALYSIS_SCALES_S:
            scale_mask = np.isclose(scale_values, float(scale))
            available: list[str] = []
            models: list[object] = []
            for subclass in subclasses:
                indices = np.where(scale_mask & subclass_values.eq(subclass).to_numpy(bool))[0]
                if len(indices) == 0:
                    continue
                class_k = min(max(1, k_neighbors // 2), len(indices))
                models.append(base.refine.NearestNeighbors(n_neighbors=class_k, metric='euclidean').fit(z[indices]))
                available.append(subclass)
            target_indices = np.where(scale_mask)[0]
            if not available or not len(target_indices):
                continue
            class_distance = np.column_stack([model.kneighbors(z[target_indices], return_distance=True)[0][:, -1] for model in models])
            best_position = np.argmin(class_distance, axis=1)
            labels = np.asarray(available, dtype=object)
            result.loc[target_indices, 'nearest_noise_subclass'] = labels[best_position]
            result.loc[target_indices, 'nearest_noise_subclass_distance'] = class_distance[np.arange(len(target_indices)), best_position]
        return result
    original_add_noise_domain_distances: Callable = base.refine.add_noise_domain_distances

    def add_noise_domain_distances_s2(features: pd.DataFrame):
        enriched = attach_reference_subclass(features)
        scored, calibration, bundle = original_add_noise_domain_distances(enriched)
        scored = add_subclass_diagnostics(scored, bundle['z'], tuple(REFERENCE_SUBCLASS_COUNTS))
        bundle['reference_subclasses'] = list(REFERENCE_SUBCLASS_COUNTS)
        return (scored, calibration, bundle)
    original_aggregate_candidate_screening: Callable = base.refine.aggregate_candidate_screening

    def aggregate_candidate_screening_s2(scored: pd.DataFrame, events: pd.DataFrame):
        catalog, votes = original_aggregate_candidate_screening(scored, events)
        candidates = scored[scored['task_class'].astype(str).eq('candidate')].copy()
        if 'nearest_noise_subclass' in candidates and (not candidates.empty):
            ratio = pd.to_numeric(candidates['noise_distance_ratio'], errors='coerce')
            candidates = candidates.assign(_ratio=ratio)
            best = candidates.loc[candidates.groupby('physical_event_id')['_ratio'].idxmax(), ['physical_event_id', 'nearest_noise_subclass', 'nearest_noise_subclass_distance']].rename(columns={'nearest_noise_subclass': 'best_nearest_noise_subclass', 'nearest_noise_subclass_distance': 'best_nearest_noise_subclass_distance'})
            catalog = catalog.merge(best, on='physical_event_id', how='left', validate='one_to_one')
        return (catalog, votes)
    original_build_four_reference_scored: Callable = base.build_four_reference_scored

    def build_four_reference_scored_s2(baseline_scored, baseline_bundle, events):
        scored, calibration, reference_events, bundle = original_build_four_reference_scored(baseline_scored, baseline_bundle, events)
        if 'reference_subclass' not in scored:
            scored = attach_reference_subclass(scored)
        early_mask = scored['task_class'].astype(str).eq(EARLY_REFERENCE_CLASS)
        scored.loc[early_mask, 'reference_subclass'] = EARLY_REFERENCE_CLASS
        subclasses = tuple(REFERENCE_SUBCLASS_COUNTS) + (EARLY_REFERENCE_CLASS,)
        scored = add_subclass_diagnostics(scored, bundle['z'], subclasses)
        bundle['reference_subclasses'] = list(subclasses)
        return (scored, calibration, reference_events, bundle)
    original_add_tags: Callable = base.add_formal_screening_tags

    def add_formal_screening_tags(catalog: pd.DataFrame) -> pd.DataFrame:
        result = original_add_tags(catalog)
        peak = pd.to_datetime(result['peak_time'], errors='coerce')
        result['event_phase'] = np.where(peak.ge(MACRO_OBSERVATION), 'post_macro', 'pre_macro')
        result['is_precursory_candidate'] = peak.lt(MACRO_OBSERVATION)
        return result
    original_readme: Callable = base.write_method_readme

    def write_method_readme(baseline_catalog: pd.DataFrame, four_catalog: pd.DataFrame) -> None:
        original_readme(baseline_catalog, four_catalog)
        note = {'experiment': 'S2_no_crack', 'reference_subclass_counts': dict(REFERENCE_SUBCLASS_COUNTS), 'reference_subclass_to_s1_parent': dict(REFERENCE_SUBCLASS_TO_PARENT), 's1_parent_reference_counts': dict(REFERENCE_COUNTS), 'reference_sampling_policy': 'Seven S2 experimental subclasses are sampled separately; routine_personnel is sampled from its pooled valid times and recurring mixed_personnel_pumping is balanced across episodes.', 'mixed_nuisance_policy': {'mixed_personnel_pumping': 'Included as a capped reference subclass because it recurs in three documented intervals.', 'mixed_personnel_scanner_pumping': 'Hard exclusion only because it is a single three-source episode.'}, 'early30_internal_label': EARLY_REFERENCE_CLASS, 'early30_window': {'start': base.EXPERIMENT_START.isoformat(), 'end': base.EARLY30_END.isoformat(), 'meaning': 'S1-equivalent fourth-domain sensitivity branch from the first 30 min of rainfall'}, 'knn_core_policy': 'Unchanged from S1: all baseline reference rows are pooled within each scale and share one leave-one-out distance threshold.', 'macro_observation': MACRO_OBSERVATION.isoformat(), 'analysis_end': ANALYSIS_END.isoformat(), 'reference_safe_end': REFERENCE_SAFE_END.isoformat(), 'raw_detection_baseline_policy': {'type': 'S1-equivalent stage-conditioned background', 'sampling': 'Every 10 s from pre-macro H5 data, excluding documented operation intervals and their buffers.', 'per_stage_limit': int(getattr(base, 'CALIBRATION_TIMES_PER_STAGE', 48)), 'excluded_after': REFERENCE_SAFE_END.isoformat(), 'post_macro_detection': f'Stage(s) {POST_MACRO_STAGE_IDS} use frozen stage-{POST_MACRO_ANCHOR_STAGE_ID} models for detection only and are excluded from calibration.'}, 'post_macro_policy': 'Events after 20:37:47 are retained but cannot be described as precursory.'}
        (OUTPUT_DIR / 'S2_run_interpretation.json').write_text(json.dumps(note, ensure_ascii=False, indent=2), encoding='utf-8')
    base.load_network_and_stages = load_network_and_stages
    base.operation_status = operation_status
    base.calibration_times = calibration_times
    base.build_calibration = build_calibration_with_post_macro_holdout
    base.add_formal_screening_tags = add_formal_screening_tags
    base.write_method_readme = write_method_readme
    base.build_four_reference_scored = build_four_reference_scored_s2
    base.refine.build_feature_tasks = build_feature_tasks
    base.refine.task_cache_signature = s2_task_cache_signature
    base.refine.add_noise_domain_distances = add_noise_domain_distances_s2
    base.refine.aggregate_candidate_screening = aggregate_candidate_screening_s2

def main() -> int:
    require_inputs()
    base = load_s1_script()
    install_s2_adapter(base)
    install_stage4_cache_repair(base)
    return int(base.main(sys.argv[1:]))
if __name__ == '__main__':
    raise SystemExit(main())
